<?php

/**
 * Hand-written code. NOT generated by Speakeasy. Safe from regeneration.
 *
 * @see docs/REGENERATION.md
 */

declare(strict_types=1);

namespace Factuarea\Sdk\Custom\Request;

use Factuarea\Sdk\Utils\Retry\PermanentError;
use GuzzleHttp\ClientInterface;
use GuzzleHttp\Promise\PromiseInterface;
use Psr\Http\Message\RequestInterface;
use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\UriInterface;

/**
 * Applies the active {@see RequestOverrides} scope (explicit `null` fields and
 * extra headers) to outgoing requests. Without an active scope it is a
 * transparent pass-through.
 *
 * Generated operations pass the serialized JSON body and headers in the Guzzle
 * options, which is where this decorator rewrites them.
 */
final class RequestOverridesClient implements ClientInterface
{
    public function __construct(private readonly ClientInterface $client)
    {
    }

    /** @param array<string, mixed> $options */
    public function send(RequestInterface $request, array $options = []): ResponseInterface
    {
        return $this->client->send($request, $this->apply($request->getMethod(), $options));
    }

    /** @param array<string, mixed> $options */
    public function sendAsync(RequestInterface $request, array $options = []): PromiseInterface
    {
        return $this->client->sendAsync($request, $this->apply($request->getMethod(), $options));
    }

    /**
     * @param  string|UriInterface  $uri
     * @param  array<string, mixed>  $options
     */
    public function request(string $method, $uri, array $options = []): ResponseInterface
    {
        return $this->client->request($method, $uri, $this->apply($method, $options));
    }

    /**
     * @param  string|UriInterface  $uri
     * @param  array<string, mixed>  $options
     */
    public function requestAsync(string $method, $uri, array $options = []): PromiseInterface
    {
        return $this->client->requestAsync($method, $uri, $this->apply($method, $options));
    }

    public function getConfig(?string $option = null): mixed
    {
        return $this->client->getConfig($option);
    }

    /**
     * @param  array<string, mixed>  $options
     * @return array<string, mixed>
     */
    private function apply(string $method, array $options): array
    {
        $scope = RequestOverrides::current();
        if ($scope === null) {
            return $options;
        }

        foreach ($scope['headers'] as $name => $value) {
            $options['headers'] = self::withoutHeader($options['headers'] ?? [], $name);
            $options['headers'][$name] = $value;
        }

        if ($scope['clear'] !== []) {
            if (! in_array(strtoupper($method), ['POST', 'PUT', 'PATCH'], true)) {
                throw new \LogicException(sprintf('Cannot clear fields on a %s request: it has no JSON body.', strtoupper($method)));
            }
            try {
                $options = self::withNulls($options, $scope['clear']);
            } catch (\LogicException $e) {
                // The generated retry loop retries any other exception until it
                // times out; a permanent error is rethrown as is (its previous).
                throw new PermanentError($e->getMessage(), 0, $e);
            }
        }

        return $options;
    }

    /**
     * @param  array<string, mixed>  $options
     * @param  list<string>  $paths
     * @return array<string, mixed>
     */
    private static function withNulls(array $options, array $paths): array
    {
        $raw = $options['body'] ?? null;
        $body = new \stdClass();
        if (is_string($raw) && $raw !== '') {
            $decoded = json_decode($raw);
            if (! $decoded instanceof \stdClass) {
                throw new \LogicException('Cannot clear fields: the request body is not a JSON object.');
            }
            $body = $decoded;
        } elseif ($raw !== null && $raw !== '') {
            throw new \LogicException('Cannot clear fields: the request body is not a JSON string.');
        }

        foreach ($paths as $path) {
            $node = $body;
            $segments = explode('.', $path);
            $last = array_pop($segments);
            foreach ($segments as $segment) {
                if (! property_exists($node, $segment) || $node->{$segment} === null) {
                    $node->{$segment} = new \stdClass();
                }
                if (! $node->{$segment} instanceof \stdClass) {
                    throw new \LogicException(sprintf('Cannot clear "%s": "%s" is not an object.', $path, $segment));
                }
                $node = $node->{$segment};
            }
            if (property_exists($node, $last) && $node->{$last} !== null) {
                throw new \LogicException(sprintf('Cannot clear "%s": the request already sends a value for it.', $path));
            }
            $node->{$last} = null;
        }

        $options['body'] = json_encode($body, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION | JSON_THROW_ON_ERROR);
        if (! self::hasHeader($options['headers'] ?? [], 'Content-Type')) {
            $options['headers']['Content-Type'] = 'application/json';
        }

        return $options;
    }

    private static function hasHeader(mixed $headers, string $name): bool
    {
        if (! is_array($headers)) {
            return false;
        }

        foreach (array_keys($headers) as $headerName) {
            if (is_string($headerName) && strcasecmp($headerName, $name) === 0) {
                return true;
            }
        }

        return false;
    }

    /**
     * @return array<string, mixed>
     */
    private static function withoutHeader(mixed $headers, string $name): array
    {
        $kept = [];
        foreach (is_array($headers) ? $headers : [] as $headerName => $value) {
            if (! is_string($headerName) || strcasecmp($headerName, $name) !== 0) {
                $kept[$headerName] = $value;
            }
        }

        return $kept;
    }
}
